// src/components/InventoryTable.tsx
// Read-only list of unitStocks + grand total + export buttons.
// Exports are generated by the backend: we POST the list and the chosen format,
// and download whatever file the endpoint returns.
import { useMemo, useState } from 'react';
import { apiFetch } from '../api';
import type { UnitStock } from '../types/inventory';

type ExportFormat = 'xlsx' | 'csv' | 'pdf' | 'txt';

// Replace with your real route
const EXPORT_URL = '/api/reports/inventory';

interface InventoryTableProps {
    unitStocks: UnitStock[];
    isLoading?: boolean;
    error?: string | null;
    onClose?: () => void;
}

// Same number style as ProduceBatchModal: "$" prefix, 2 decimals, no thousands separator
const money = (n: number) => `$${n.toFixed(2)}`;
// Quantities are shown as plain numbers (rounded to 6 decimals to hide floating-point noise)
const qty = (n: number) => String(Math.round(n * 1e6) / 1e6);

// Reads the file name from the Content-Disposition header, if the server sent one
function fileNameFrom(response: Response, fallback: string): string {
    const header = response.headers.get('Content-Disposition') ?? '';
    const utf8 = /filename\*=UTF-8''([^;]+)/i.exec(header);
    if (utf8) return decodeURIComponent(utf8[1]);
    const plain = /filename="?([^";]+)"?/i.exec(header);
    return plain ? plain[1] : fallback;
}

export default function InventoryTable({ unitStocks, isLoading = false, error = null, onClose, }: InventoryTableProps) {
    const [exporting, setExporting] = useState<ExportFormat | null>(null);
    const [exportError, setExportError] = useState<string | null>(null);

    const rows = useMemo(
        () =>
            unitStocks.map((us) => ({
                id: us.id,
                name: us.unit.name,
                sku: us.unit.sku,
                measurement: us.unit.measurement,
                quantity: us.quantity,
                price: us.price,
                total: us.quantity * us.price,
            })),
        [unitStocks]
    );

    const grandTotal = useMemo(() => rows.reduce((sum, r) => sum + r.total, 0), [rows]);

    const exportReport = async (format: ExportFormat) => {
        setExporting(format);
        setExportError(null);
        try {
            const response = await apiFetch(EXPORT_URL, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ format, items: unitStocks }),
            });
            if (response.status === 401) throw new Error('Session expired. Please sign in again.');
            if (!response.ok) throw new Error(`Export failed (${response.status})`);

            const blob = await response.blob();
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = fileNameFrom(response, `inventory.${format}`);
            a.click();
            URL.revokeObjectURL(url);
        } catch (err: any) {
            setExportError(err.message || 'Export failed.');
        } finally {
            setExporting(null);
        }
    };

    const canExport = rows.length > 0 && exporting === null;

    const exportButtons: { format: ExportFormat; label: string; title: string; color: string }[] = [
        { format: 'xlsx', label: 'XLSX', title: 'Export to Excel', color: '#22c55e' },
        { format: 'csv', label: 'CSV', title: 'Export to CSV', color: '#38bdf8' },
        { format: 'pdf', label: 'PDF', title: 'Export to PDF', color: '#fb7185' },
        { format: 'txt', label: 'TXT', title: 'Export to text file', color: '#cbd5e1' },
    ];

    const th: React.CSSProperties = {
        padding: '12px 16px',
        fontSize: '13px',
        fontWeight: 600,
        color: '#94a3b8',
        borderBottom: '1px solid #334155',
        textAlign: 'left',
        position: 'sticky',
        top: 0,
        backgroundColor: '#1e293b',
    };
    const td: React.CSSProperties = {
        textAlign: 'left',
        padding: '12px 16px',
        fontSize: '14px',
        color: '#e2e8f0',
        borderBottom: '1px solid rgba(51, 65, 85, 0.6)',
    };
    const num: React.CSSProperties = { textAlign: 'right', fontVariantNumeric: 'tabular-nums' };

    const message = exportError ?? error;

    return (
        <div style={{ display: 'flex', flexDirection: 'column', width: '100%', height: '100%', fontFamily: 'monospace', position: 'relative', }}>
            <div
                style={{
                    flex: 1,
                    minHeight: 0,
                    overflow: 'auto',
                    paddingTop: '48px',
                    scrollbarWidth: 'thin',
                    scrollbarColor: 'rgba(20, 184, 166, 0.5) #0f172a', // same dark theme scrollbar as the modals
                }}
            >
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                    <thead>
                        <tr>
                            <th style={th}>Name</th>
                            <th style={th}>SKU</th>
                            <th style={th}>Unit</th>
                            <th style={{ ...th, ...num }}>Quantity</th>
                            <th style={{ ...th, ...num }}>Price per unit</th>
                            <th style={{ ...th, ...num }}>Total price</th>
                        </tr>
                    </thead>
                    <tbody>
                        {rows.map((r) => (
                            <tr key={r.id}>
                                <td style={td}>{r.name}</td>
                                <td style={{ ...td, color: '#94a3b8' }}>{r.sku}</td>
                                <td style={{ ...td, color: '#94a3b8' }}>{r.measurement}</td>
                                <td style={{ ...td, ...num }}>{qty(r.quantity)}</td>
                                <td style={{ ...td, ...num }}>{money(r.price)}</td>
                                <td style={{ ...td, ...num }}>{money(r.total)}</td>
                            </tr>
                        ))}
                        {rows.length === 0 && (
                            <tr>
                                <td colSpan={6} style={{ ...td, textAlign: 'center', color: '#94a3b8', padding: '32px' }}>
                                    {isLoading ? 'Loading inventory…' : 'No materials in stock yet.'}
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            {/* Footer: export buttons on the left, grand total on the right */}
            <div
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: '16px',
                    padding: '10px 16px',
                    borderTop: '1px solid #334155',
                    backgroundColor: '#1e293b',
                }}
            >
                <div style={{ display: 'flex', gap: '8px' }}>
                    {exportButtons.map((b) => (
                        <button
                            key={b.format}
                            type="button"
                            title={b.title}
                            aria-label={b.title}
                            disabled={!canExport}
                            onClick={() => exportReport(b.format)}
                            style={{
                                background: 'transparent',
                                border: '1px solid #334155',
                                borderRadius: '8px',
                                padding: '4px',
                                cursor: canExport ? 'pointer' : 'not-allowed',
                                opacity: exporting === b.format ? 0.6 : canExport ? 1 : 0.4,
                                color: b.color,
                                display: 'flex',
                            }}
                        >
                            <FileIcon label={exporting === b.format ? '...' : b.label} />
                        </button>
                    ))}
                </div>

                {message && <span style={{ color: '#fb7185', fontSize: '13px' }}>{message}</span>}

                <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px' }}>
                    <span style={{ fontSize: '15px', fontWeight: 600, color: '#e2e8f0' }}>Grand total:</span>
                    <span style={{ fontSize: '15px', fontWeight: 600, color: '#2dd4bf', fontVariantNumeric: 'tabular-nums' }}>
                        {money(grandTotal)}
                    </span>
                </div>
            </div>
            {onClose && (
                <button
                    type="button"
                    onClick={onClose}
                    style={{
                        position: 'absolute',
                        top: '8px',
                        right: '12px',
                        width: '32px',
                        height: '32px',
                        borderRadius: '6px',
                        border: '1px solid #334155',
                        background: '#1e293b',
                        color: '#94a3b8',
                        cursor: 'pointer',
                        fontFamily: 'monospace',
                        fontSize: '18px',
                        fontWeight: 'bold',
                        zIndex: 9999,
                    }}
                >
                    ×
                </button>
            )}
        </div>
    );
}

// Small document icon with the file type written on it
function FileIcon({ label }: { label: string }) {
    return (
        <svg width="34" height="34" viewBox="0 0 34 34" fill="none" aria-hidden="true">
            <path
                d="M9 4h11l6 6v19a1 1 0 0 1-1 1H9a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1Z"
                stroke="currentColor"
                strokeWidth="1.6"
                strokeLinejoin="round"
            />
            <path d="M20 4v6h6" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
            <text x="17" y="24" textAnchor="middle" fontSize="7" fontWeight="700" fill="currentColor" fontFamily="monospace">
                {label}
            </text>
        </svg>
    );
}
